er');return{marker,node:process.version,files,backup:ref.backup,tools,rows,rows_sha256:ref.rows_sha256,restored_from_archive:true,before:JSON.parse(fs.readFileSync('qa402-before.json'))}}\\nif(phase==='build'){const v=restore();fs.writeFileSync('qa402-build.json',JSON.stringify(v));console.log('QA402_AFTER '+JSON.stringify(v))}else{http.createServer((req,res)=\u003e{if(req.url.split('?')[0]!=='/'\u0026\u0026req.url.split('?')[0]!=='/restore'){res.writeHead(404);return res.end()}try{const runtime={...restore(),request_url:req.url};res.setHeader('Content-Type','application/json');res.end(JSON.stringify({build:require('./qa402-build.json'),runtime}));console.log('QA402_RUNTIME '+JSON.stringify(runtime))}catch(e){res.writeHead(500);res.end(String(e))}}).listen(Number(process.env.PORT),'0.0.0.0')}\\nQA402_QA402_PROBE_CJS\\ncat \u003e qa402-reference.json \u003c\u003c'QA402_QA402_REFERENCE_JSON'\\n{\"repo\":\"https://github.com/git-fixtures/basic\",\"branch\":\"master\",\"commit\":\"6ecf0ef2c2dffb796033e5a02219af86ec6584e5\",\"files\":{\"LICENSE\":{\"bytes\":1072,\"sha256\":\"20b064910b32bce1bc04595a5b20477a28c503995ef8528929a311d6cb7a3b09\"},\"CHANGELOG\":{\"bytes\":18,\"sha256\":\"9c65e366055edd9a0f6ab9c7b8a37fc92803cfe1d30ffa727ceed0c63939c2e5\"}},\"backup\":{\"bytes\":1721,\"sha256\":\"5beaea91d80ee9a3f7f637bd096446102952aa20a916f614fcb73575d1ece4a4\"},\"rows\":[\"INSERT INTO public.qa402_backup VALUES (1, 'QA402 alpha');\",\"INSERT INTO public.qa402_backup VALUES (2, 'QA402 caf\\u00e9 \\u96ea');\",\"INSERT INTO public.qa402_backup VALUES (3, 'QA402 quote '' and comma,');\"],\"rows_sha256\":\"5090a6d28f0eddaa146a603028c04deaa63c6c796a16fe07ae7c81a10ae85624\"}\\nQA402_QA402_REFERENCE_JSON\\ncat \u003e qa402-marker.json \u003c\u003c'QA402_QA402_MARKER_JSON'\\n\"QA402_92b368_render\"\\nQA402_QA402_MARKER_JSON\\nnode qa402-probe.cjs before\\napt-get update -qq \u0026\u0026 apt-get install -y --no-install-recommends postgresql-client\\npg_restore --data-only --no-owner --n